import{_ as e,o as i,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"this 关键字的指向","description":"在 JavaScript 中，this 关键字的指向依赖于函数调用的上下文。不同的调用方式会导致 this 指向不同的对象。下面简述 this 的常见指向情况： 1. 全局上下文 在全局范围内，this 指向全局对象。在浏览器中，全局对象是 window。 console.log。","frontmatter":{"title":"this 关键字的指向","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"在 JavaScript 中，this 关键字的指向依赖于函数调用的上下文。不同的调用方式会导致 this 指向不同的对象。下面简述 this 的常见指向情况： 1. 全局上下文 在全局范围内，this 指向全局对象。在浏览器中，全局对象是 window。 console.log。","sidebarWeight":12,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/引用数据类型-函数/(20m)[重]this对象/this 关键字的指向.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(20m)[重]this对象/this 关键字的指向.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(20m)[重]this对象/this 关键字的指向.md"}'),s={name:"posts/JavaScript系统教程/03-对象、数组与函数/(20m)[重]this对象/this 关键字的指向.md"};function l(a,t,r,h,c,p){return i(),o("div",null,[...t[0]||(t[0]=[n('<div><h1 id="this-关键字的指向" tabindex="-1">this 关键字的指向 <a class="header-anchor" href="#this-关键字的指向" aria-label="Permalink to &quot;this 关键字的指向&quot;">​</a></h1><blockquote><p>本节目标：理解“this 关键字的指向”的核心思路，并能把它用于实际开发或面试表达。 在 JavaScript 中，this 关键字的指向依赖于函数调用的上下文。不同的调用方式会导致 this 指向不同的对象。下面简述 this 的常见指向情况：</p></blockquote><ol><li><p>全局上下文 在全局范围内，this 指向全局对象。在浏览器中，全局对象是 window。 console.log(this); // 在浏览器中，输出: window</p></li><li><p>函数调用 在普通函数调用中，this 默认指向全局对象（在严格模式下指向 undefined）。 function foo() { console.log(this); } foo(); // 在浏览器中，输出: window；在严格模式下，输出: undefined</p></li><li><p>方法调用 当方法作为对象的属性被调用时，this 指向调用该方法的对象。 let obj = { name: &#39;Alice&#39;, greet: function() { console.log(this.name); } }; obj.greet(); // 输出: Alice</p></li><li><p>构造函数调用 当使用 new 关键字调用构造函数时，this 指向新创建的对象。 function Person(name) { this.name = name; } let person = new Person(&#39;Bob&#39;); console.log(person.name); // 输出: Bob</p></li><li><p>call 和 apply 使用 call 或 apply 方法调用函数时，this 指向第一个参数指定的对象。 function greet() { console.log(this.name); } let obj = { name: &#39;Charlie&#39; }; greet.call(obj); // 输出: Charlie greet.apply(obj); // 输出: Charlie</p></li><li><p>bind 使用 bind 方法可以创建一个新的函数，这个函数的 this 永远指向 bind 的第一个参数指定的对象。 function greet() { console.log(this.name); } let obj = { name: &#39;Dave&#39; }; let boundGreet = greet.bind(obj); boundGreet(); // 输出: Dave</p></li><li><p>箭头函数 箭头函数不会创建自己的 this，它会捕获所在上下文的 this 作为自己的 this 值。 let obj = { name: &#39;Eve&#39;, greet: function() { let inner = () =&gt; { console.log(this.name); }; inner(); } }; obj.greet(); // 输出: Eve</p></li><li><p>DOM 事件处理程序 在 DOM 事件处理程序中，this 指向绑定事件的元素。 let button = document.getElementById(&#39;myButton&#39;); button.addEventListener(&#39;click&#39;, function() { console.log(this); // 输出: &lt;button id=&quot;myButton&quot;&gt;...&lt;/button&gt; });</p></li></ol></div>',1)])])}const u=e(s,[["render",l]]);export{m as __pageData,u as default};
